// Helper do kompaktowego dorzucania słówek partiami (po levelu w danej kategorii).
// Użycie:  ...tier("verbs", "A1", [["być", "be"], ["mieć", "have"]])
function tier(category, level, pairs) {
  return pairs.map(([pl, en]) => ({ pl, en, category, level }));
}

