export function getRandomWord(category) {
  const pool = category ? WORDS.filter((w) => w.category === category) : WORDS;
  if (pool.length === 0) return WORDS[Math.floor(Math.random() * WORDS.length)];
  return pool[Math.floor(Math.random() * pool.length)];
}

// Mapa "pl po normalizacji → poziom" — używana do auto-uzupełniania poziomu
// w custom taliach. Klucz = lowercased + trimmed. Lazy-init po pierwszym
// wywołaniu, dlatego dodanie nowych WORDS w trakcie sesji nie aktualizuje
// mapy (akceptowalne — WORDS jest stałe po imporcie modułu).
let _plLevelMap = null;
export function lookupLevelByPl(pl) {
  if (!pl) return null;
  if (_plLevelMap === null) {
    _plLevelMap = new Map();
    for (const w of WORDS) {
      _plLevelMap.set(w.pl.trim().toLowerCase(), w.level || null);
    }
  }
  return _plLevelMap.get(pl.trim().toLowerCase()) ?? null;
}
